import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"کاپی آئینہ ٹیکنالوجی کا اصول","description":"","frontmatter":{},"headers":[],"relativePath":"ur/63-复制镜技术原理.md","filePath":"ur/63-复制镜技术原理.md","lastUpdated":1789183869000}'),o={name:"ur/63-复制镜技术原理.md"};function l(i,t,n,h,s,_){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="کاپی-آئینہ-ٹیکنالوجی-کا-اصول" tabindex="-1">کاپی آئینہ ٹیکنالوجی کا اصول <a class="header-anchor" href="#کاپی-آئینہ-ٹیکنالوجی-کا-اصول" aria-label="Permalink to &quot;کاپی آئینہ ٹیکنالوجی کا اصول&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>63</td></tr><tr><td>ماڈیول</td><td>ٹیکنالوجی اور توانائی کا نظام</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>کاپی آئینہ، آئینہ کاپی، آثار قدیمہ کی اسکیم، کم آلودگی، خلائی قانون</td></tr></tbody></table><h2 id="_1-کاپی-آئینہ-ٹیکنالوجی-کی-پوزیشن-اور-اصل" tabindex="-1">1. کاپی آئینہ ٹیکنالوجی کی پوزیشن اور اصل <a class="header-anchor" href="#_1-کاپی-آئینہ-ٹیکنالوجی-کی-پوزیشن-اور-اصل" aria-label="Permalink to &quot;1. کاپی آئینہ ٹیکنالوجی کی پوزیشن اور اصل&quot;">​</a></h2><p>کاپی آئینہ ٹیکنالوجی اینکر سمبیوٹک تہذیب کے آثار قدیمہ کی اسکیم کی دو بنیادی ٹیکنالوجیز میں سے ایک ہے (دوسری الگ تھلگ خلا کی تعمیر کی ٹیکنالوجی ہے)، اس کا بنیادی کام ہدف والے طیارے یا ہدف والے علاقے کی اعلیٰ درستگی کی آئینہ کاپی کرنا ہے، جس سے آثار قدیمہ اور تحقیق کا کام کاپی میں کیا جا سکتا ہے، اور اس طرح اصل طیارے میں مداخلت اور آلودگی سے بچا جا سکتا ہے۔</p><p>کاپی آئینہ ٹیکنالوجی کی اصل خلائی قانون کی شیڈولنگ کے نظام کے &quot;خلا کی تبدیلی&quot; کے شعبے کی تحقیق تک جائی جا سکتی ہے۔ تحقیقی ٹیم نے خلا-مادے کی تبدیلی کے میکانزم کی تلاش کے دوران دریافت کیا کہ ہدف والے علاقے کے خلائی ڈھانچے کے مکمل قانون اسکیننگ اور دوبارہ تعمیر کے ذریعے، کسی دوسرے خلا میں اصل علاقے سے بہت زیادہ مطابقت رکھنے والی آئینہ کاپی تیار کی جا سکتی ہے۔ یہ دریافت، بہت زیادہ بہتری کے تکرار کے ذریعے ضرب پھل تخمینہ انجن کے ذریعے، آخر میں کاپی آئینہ کا نظام بن گیا جسے انجینئرنگ کے ذریعے لاگو کیا جا سکتا ہے۔</p><h2 id="_2-کاپی-آئینہ-کے-کام-کا-اصول" tabindex="-1">2. کاپی آئینہ کے کام کا اصول <a class="header-anchor" href="#_2-کاپی-آئینہ-کے-کام-کا-اصول" aria-label="Permalink to &quot;2. کاپی آئینہ کے کام کا اصول&quot;">​</a></h2><p>کاپی آئینہ کے کام کا عمل چار مراحل میں تقسیم ہے، ہر مرحلے میں سخت ٹیکنالوجی پیرامیٹرز اور حفاظتی حد ہیں:</p><table tabindex="0"><thead><tr><th>مرحلہ</th><th>نام</th><th>فنکشن کی وضاحت</th><th>کلیدی پیرامیٹرز</th></tr></thead><tbody><tr><td>پہلا مرحلہ</td><td>قانون اسکیننگ</td><td>ہدف والے علاقے کی تمام جہتوں کی قانون اسکیننگ کرنا، خلائی ڈھانچہ، مادے کی تقسیم، توانائی کا میدان، شعور کی باقیات وغیرہ جیسی تمام معلومات حاصل کرنا</td><td>اسکیننگ کی درستگی 0.001 قانون منٹ سے کم نہیں، اسکیننگ کی کوریج ≥99.99%</td></tr><tr><td>دوسرا مرحلہ</td><td>معلومات کی انکوڈنگ</td><td>اسکیننگ سے حاصل کردہ بہت زیادہ معلومات کو منتقل ہونے کے قابل قانون ڈیٹا پیکٹ میں انکوڈ کرنا، بے کار چیزوں کو ہٹانا اور مکمل ہونے کی تصدیق کرنا</td><td>انکوڈنگ کمپریشن کا تناسب تقریباً 10^6:1، تصدیق اینکر ہیش الگورتھم کا استعمال کرتی ہے</td></tr><tr><td>تیسرا مرحلہ</td><td>آئینہ دوبارہ تعمیر</td><td>قانون ڈیٹا پیکٹ کے مطابق الگ تھلگ خلا میں ہدف والے علاقے کی آئینہ کاپی دوبارہ بنانا</td><td>دوبارہ تعمیر کی وفاداری ≥99.95%، دوبارہ تعمیر میں انحراف قابو پانے والی حد میں ہونا چاہیے</td></tr><tr><td>چوتھا مرحلہ</td><td>ہم آہنگی کیلیبریشن</td><td>آئینہ کاپی اور اصل علاقے کے درمیان مسلسل ہم آہنگی کیلیبریشن کرنا، اس بات کو یقینی بنانا کہ تحقیق کے عمل میں ہونے والی تبدیلیوں کا پتہ لگایا جا سکے</td><td>ہم آہنگی میں تاخیر ≤0.1 سیکنڈ، کیلیبریشن کی فریکوئنسی تحقیق کی ضرورت کے مطابق ایڈجسٹ کی جا سکتی ہے</td></tr></tbody></table><p>کاپی آئینہ کی &quot;کاپی&quot; سادہ مادے کی کلوننگ نہیں ہے، بلکہ خلائی قانون کی بنیاد پر قانون کی سطح کی دوبارہ تعمیر ہے۔ آئینہ کاپی جسمانی ڈھانچے، توانائی کی تقسیم اور یہاں تک کہ شعور کی باقیات کی سطح میں بھی اصل علاقے سے بہت زیادہ مطابقت رکھتی ہے، لیکن یہ بنیادی طور پر ایک آزاد خلائی مثال ہے، اس کے اندرونی تبدیلیاں اصل علاقے کو بالکل متاثر نہیں کرتیں۔</p><h2 id="_3-کاپی-آئینہ-سسٹم-کی-انجینئرنگ-آرکیٹیکچر" tabindex="-1">3. کاپی آئینہ سسٹم کی انجینئرنگ آرکیٹیکچر <a class="header-anchor" href="#_3-کاپی-آئینہ-سسٹم-کی-انجینئرنگ-آرکیٹیکچر" aria-label="Permalink to &quot;3. کاپی آئینہ سسٹم کی انجینئرنگ آرکیٹیکچر&quot;">​</a></h2><p>کاپی آئینہ سسٹم انجینئرنگ میں تین بڑے سب سسٹمز پر مشتمل ہے:</p><ol><li><strong>اسکیننگ سب سسٹم</strong>: ہدف والے طیارے کے قریب نافذ کردہ قانون اسکیننگ سرنی، خلائی ادراک ماڈیول سے چلتی ہے، سیارے کی سطح سے علاقائی سطح تک مختلف پیمانے کے اہداف کو اسکین کر سکتی ہے۔ اسکیننگ سرنی غیر حملہ آور ڈیزائن اپناتی ہے، صرف غیر فعال طور پر قانون کی معلومات حاصل کرتی ہے، ہدف والے علاقے میں کوئی توانائی خارج نہیں کرتی</li><li><strong>ٹرانسمیشن سب سسٹم</strong>: طیاروں کے درمیان مواصلاتی ٹیکنالوجی پر مبنی قانون ڈیٹا ٹرانسمیشن چینل، انکوڈ کردہ اسکیننگ ڈیٹا کو اس تحقیقی اسٹیشن پر منتقل کرتا ہے جہاں الگ تھلگ خلا واقع ہے۔ ٹرانسمیشن کے عمل میں اینڈ ٹو اینڈ انکرپشن کا استعمال کیا جاتا ہے، ٹرانسمیشن کے دوران قانون ڈیٹا کو تبدیل کرنے یا چوری کرنے سے روکتا ہے</li><li><strong>دوبارہ تعمیر سب سسٹم</strong>: الگ تھلگ خلا کے اندر نافذ کردہ آئینہ دوبارہ تعمیر سرنی، خلائی تبدیلی ماڈیول سے چلتی ہے، قانون ڈیٹا پیکٹ کے مطابق الگ تھلگ خلا میں ہدف والا علاقہ دوبارہ بناتی ہے۔ دوبارہ تعمیر سرنی کا پیمانہ زیادہ سے زیادہ کاپی کیے جانے والے علاقے کے پیمانے کا تعین کرتا ہے</li></ol><p>کاپی آئینہ سسٹم کی تعیناتی کی سطح تین سطحوں میں تقسیم ہے:</p><ul><li><strong>سیارے کی سطح</strong>: مکمل سیارے کی آئینہ کاپی کر سکتی ہے، تہذیب کی سطح کے آثار قدیمہ کی تحقیق کے لیے</li><li><strong>علاقائی سطح</strong>: براعظم یا ملک کے پیمانے کے علاقے کاپی کر سکتی ہے، اہم علاقوں کی تحقیق کے لیے</li><li><strong>سائٹ کی سطح</strong>: مخصوص کھنڈرات یا مناظر کاپی کر سکتی ہے، باریک آثار قدیمہ کی کھدائی کے لیے</li></ul><h2 id="_4-کاپی-آئینہ-ٹیکنالوجی-کی-اخلاقی-اور-حفاظتی-پابندیاں" tabindex="-1">4. کاپی آئینہ ٹیکنالوجی کی اخلاقی اور حفاظتی پابندیاں <a class="header-anchor" href="#_4-کاپی-آئینہ-ٹیکنالوجی-کی-اخلاقی-اور-حفاظتی-پابندیاں" aria-label="Permalink to &quot;4. کاپی آئینہ ٹیکنالوجی کی اخلاقی اور حفاظتی پابندیاں&quot;">​</a></h2><p>اگرچہ کاپی آئینہ ٹیکنالوجی طاقتور ہے، پھر بھی اس کا استعمال سخت اخلاقی اور حفاظتی پابندیوں سے منسلک ہے:</p><ul><li><strong>صرف علم کی واپسی کا اصول</strong>: آئینہ کاپی میں کی جانے والی آثار قدیمہ کی تحقیق کا نتیجہ صرف علم کی شکل میں مرکزی طیارے پر واپس بھیجا جاتا ہے، آئینہ کاپی سے کوئی بھی مادہ، توانائی یا جاندار اصل طیارے یا مرکزی طیارے پر واپس نہیں لایا جا سکتا</li><li><strong>غیر حملہ آور اصول</strong>: اسکیننگ کا عمل ہدف والے علاقے کے معمول کے کام میں کوئی مداخلت نہیں کر سکتا، اسکیننگ سرنی کو غیر فعال مشاہدے کی حالت برقرار رکھنی چاہیے</li><li><strong>آئینہ کو تباہ کرنے کا اصول</strong>: تحقیق مکمل ہونے کے بعد، آئینہ کاپی کو معیاری عمل کے مطابق محفوظ طریقے سے تباہ کرنا چاہیے، طویل مدتی محفوظ نہیں کیا جا سکتا یا دوسرے استعمال میں تبدیل نہیں کیا جا سکتا</li><li><strong>شعور کی باقیات کا انتظام</strong>: اگر آئینہ کاپی میں شعور کی باقیات شامل ہیں، تو ان کا اندازہ اور انتظام عجیب زندگی کی تین قسموں کے ضوابط کے عمل کے مطابق کیا جانا چاہیے، شعور کی باقیات کو بے جان ڈیٹا کے طور پر نہیں سمجھا جانا چاہیے</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>کاپی آئینہ ٹیکنالوجی کا اصول &quot;پہلے مشاہدہ، پھر محدود مداخلت&quot; کے اصول کا ٹیکنالوجی مظہر ہے۔ یہ ہینگیوانزھو کے محققین کو اصل طیارے کو چھوئے بغیر ہدف پر گہرے آثار قدیمہ اور تحقیق کرنے کے قابل بناتا ہے، طیاروں کے درمیان آثار قدیمہ میں آلودگی اور مداخلت کے مسئلے کو بنیادی طور پر حل کرتا ہے۔ کاپی آئینہ اور الگ تھلگ خلا کا مجموعہ، سمبیوٹک تہذیب کی کم آلودگی تحقیقی اسکیم کی ٹیکنالوجی کی بنیاد بناتا ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>64-الگ تھلگ خلا کی تعمیر کی ٹیکنالوجی</li><li>85-کاپی آئینہ دور دراز آثار قدیمہ کی اسکیم</li><li>62-خلائی قانون کی ٹیکنالوجی کا نفاذ</li></ul>',21)])])}const c=a(o,[["render",l]]);export{p as __pageData,c as default};
